    @Override JsonObject completeSnap(ActionOracleHarness h,RunResult r)throws Exception{JsonObject j=super.completeSnap(h,r);j.addProperty("aid_gate",h.word(0x438786));j.addProperty("chosen_portrait",h.word(0x4434b2));j.addProperty("selected_member",h.read(0x44273f,1)[0]&255);j.addProperty("displayed_member",h.word(0x443318));j.addProperty("medical_mode",h.word(0x438760));j.addProperty("bullet_mode",h.read(0x43565e,1)[0]&255);j.addProperty("display_cursor",h.word(0x4435c2));j.addProperty("tutorial_preference",h.word(0x439596));j.addProperty("tutorial_106",h.read(0x4042f2+106,1)[0]&255);j.addProperty("crate",hex(h.read(0x4285f4,22000)));j.addProperty("loot",hex(h.read(0x41fc74,22000)));j.addProperty("under_tiles",hex(h.read(0x437a6e,12)));j.add("aid_events",aidEvents.deepCopy());j.add("warnings",warnings.deepCopy());j.add("medical_events",medicalEvents.deepCopy());j.addProperty("item_work",hex(h.read(0x45363c,150)));j.addProperty("weapon_work",hex(h.read(0x453768,150)));j.addProperty("ammo_work",hex(h.read(0x4536d2,150)));return j;}
