    void updateRuleWork(ActionOracleHarness h,RunResult r)throws Exception{long returnPc=h.pointer(h.sp());int body=h.word(h.sp()+4);updating=true;long prior=secondaryStop;try{execute(h,r,0x11f1c8);JsonObject e=new JsonObject();e.addProperty("boundary","combatupdate2 graphics omitted; native selection and both item refresh paths");e.addProperty("body",body);e.addProperty("return",Long.toHexString(returnPc));if(body>=0&&body<6){h.jump(0x11f5ce);secondaryStop=0x11f804;execute(h,r,0x11f5e2);secondaryStop=prior;if(h.pc()==0x11f5e2){h.jump(0x11f61a);execute(h,r,0x11f664);e.addProperty("active_refresh",true);}else e.addProperty("active_refresh",false);h.jump(0x11faa8);boolean firearm=h.read(0x448aa0+body*3138+0x9dd,1)[0]!=0;secondaryStop=0x11fc4c;execute(h,r,firearm?0x11fb10:0x11fbe4);secondaryStop=prior;e.addProperty("mode_after",h.read(0x448aa0+body*3138+0x9dd,1)[0]&255);e.addProperty("item_work_after",hex(h.read(0x45363c,150)));}else if(body<10)throw new Exception("Unsupported selected UI body");medicalEvents.add(e);h.jump(0x120058);execute(h,r,returnPc);}finally{secondaryStop=prior;updating=false;}}
